+
+        for (String operator : List.of(":", "<", "<=", ">", ">=")) {
+            KqlQueryBuilder kqlQuery = new KqlQueryBuilder(Strings.format("%s %s %s", DATE_FIELD_NAME, operator, "2018-03-28"));
